		var styles_default = "/* dsh-better-workspace — panel chrome.\r\n   Every colour, radius and font comes from the host's own tokens with a literal fallback,\r\n   and the row metrics mirror the stock workspace browser (36px section header, 34px\r\n   workspace rows, 28px topic/session rows, 12px radii) so the panel reads as part of the\r\n   sidebar rather than a widget parked on top of it. */\r\n\r\n.dts-overlay {\r\n  position: absolute;\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-height: 0;\r\n  overflow: visible;\r\n  background: var(--dsw-specific-sidebar-fill, #f9fafb);\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  font-family: var(--dsw-font-family, inherit);\r\n  font-size: 14px;\r\n  line-height: 22px;\r\n}\r\n\r\n.dts-overlay * {\r\n  box-sizing: border-box;\r\n}\r\n\r\n.dts-panel {\r\n  display: flex;\r\n  flex: 1 1 auto;\r\n  min-height: 0;\r\n  flex-direction: column;\r\n}\r\n\r\n/* ---------- header ---------- */\r\n.dts-header {\r\n  flex: 0 0 auto;\r\n  padding: 0 4px 4px;\r\n}\r\n\r\n.dts-header__row {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 2px;\r\n  min-height: 34px;\r\n}\r\n\r\n.dts-header__label {\r\n  font-size: 14px;\r\n  font-weight: 400;\r\n  padding-left: 4px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-header__filter {\r\n  opacity: 0;\r\n  transition: opacity 0.14s ease;\r\n}\r\n\r\n.dts-overlay:hover .dts-header__filter,\r\n.dts-header__filter:focus-visible,\r\n.dts-header__filter.is-active,\r\n.dts-header.has-filter .dts-header__filter {\r\n  opacity: 1;\r\n}\r\n\r\n.dts-header__spacer {\r\n  flex: 1 1 auto;\r\n}\r\n\r\n.dts-header__search {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  margin: 0 0 6px;\r\n}\r\n\r\n.dts-header__chips {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 4px;\r\n  margin: 0 0 6px;\r\n  padding-left: 4px;\r\n}\r\n\r\n/* ---------- buttons ---------- */\r\n.dts-iconbtn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 28px;\r\n  height: 28px;\r\n  padding: 0;\r\n  border: 0;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: transparent;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n  cursor: pointer;\r\n  flex: 0 0 auto;\r\n}\r\n\r\n.dts-iconbtn:hover:not(:disabled) {\r\n  background: var(--dsw-specific-sidebar-nav-item-hover, rgba(38, 49, 72, 0.06));\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n}\r\n\r\n.dts-iconbtn.is-active {\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  background: var(--dsw-specific-sidebar-nav-item-active, rgba(38, 49, 72, 0.1));\r\n}\r\n\r\n.dts-iconbtn:disabled {\r\n  opacity: 0.4;\r\n  cursor: not-allowed;\r\n}\r\n\r\n.dts-btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  height: 28px;\r\n  padding: 0 10px;\r\n  border: 1px solid var(--dsw-alias-border-l3, rgba(0, 0, 0, 0.12));\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: transparent;\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  font: inherit;\r\n  font-size: 13px;\r\n  cursor: pointer;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-btn:hover:not(:disabled) {\r\n  background: var(--dsw-specific-sidebar-nav-item-hover, rgba(38, 49, 72, 0.06));\r\n}\r\n\r\n.dts-btn:disabled {\r\n  opacity: 0.45;\r\n  cursor: not-allowed;\r\n}\r\n\r\n.dts-btn--primary {\r\n  background: var(--dsw-alias-button-primary-fill, #0f1115);\r\n  border-color: transparent;\r\n  color: var(--dsw-alias-label-primary-foreground, #fff);\r\n}\r\n\r\n.dts-btn--primary:hover:not(:disabled) {\r\n  background: var(--dsw-alias-button-primary-hover, #43454a);\r\n}\r\n\r\n.dts-btn--danger {\r\n  background: var(--dsw-alias-state-error-primary, #ec1313);\r\n  border-color: transparent;\r\n  color: #fff;\r\n}\r\n\r\n.dts-btn--danger-ghost {\r\n  color: var(--dsw-alias-state-error-primary, #ec1313);\r\n  background: transparent;\r\n  border-color: transparent;\r\n}\r\n\r\n.dts-btn--ghost {\r\n  background: transparent;\r\n  border-color: transparent;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-spacer {\r\n  flex: 1 1 auto;\r\n}\r\n\r\n.dts-linkbtn {\r\n  border: 0;\r\n  background: transparent;\r\n  color: var(--dsw-alias-link, #4176e6);\r\n  font: inherit;\r\n  font-size: 12px;\r\n  cursor: pointer;\r\n  padding: 0;\r\n}\r\n\r\n/* ---------- inputs ---------- */\r\n.dts-input {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  height: 28px;\r\n  padding: 0 8px;\r\n  border: 1px solid var(--dsw-alias-border-l3, rgba(0, 0, 0, 0.12));\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: var(--dsw-alias-bg-base, #fff);\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  font: inherit;\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-input::placeholder {\r\n  color: var(--dsw-alias-label-caption, #adb2b8);\r\n}\r\n\r\n.dts-input:focus-visible,\r\n.dts-btn:focus-visible,\r\n.dts-iconbtn:focus-visible,\r\n.dts-row:focus-visible {\r\n  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsw-focus-ring-color, rgba(65, 118, 230, 0.5));\r\n  outline-offset: -1px;\r\n}\r\n\r\n/* ---------- chips ---------- */\r\n.dts-chip {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  height: 22px;\r\n  padding: 0 2px 0 8px;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: var(--dsw-specific-sidebar-nav-item-active, rgba(38, 49, 72, 0.08));\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n  max-width: 100%;\r\n}\r\n\r\n.dts-chip__text {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-chip__clear {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 18px;\r\n  height: 18px;\r\n  border: 0;\r\n  border-radius: var(--dsw-radius-xs, 4px);\r\n  background: transparent;\r\n  color: inherit;\r\n  cursor: pointer;\r\n}\r\n\r\n.dts-chip__clear:hover {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.08));\r\n}\r\n\r\n/* ---------- tree ---------- */\r\n.dts-scroll {\r\n  flex: 1 1 auto;\r\n  min-height: 0;\r\n  overflow-y: auto;\r\n  overflow-x: hidden;\r\n  padding: 0 4px 16px;\r\n  scrollbar-width: thin;\r\n  scrollbar-color: var(--dsw-alias-scrollbar-bg-l1, #e5e5e5) transparent;\r\n}\r\n\r\n.dts-tree {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n}\r\n\r\n/* Keep a workspace group (including its archived bucket) visually apart from the next. */\r\n.dts-group + .dts-group {\r\n  margin-top: 6px;\r\n}\r\n\r\n.dts-group__body {\r\n  display: flex;\r\n  flex-direction: column;\r\n}\r\n\r\n.dts-section--archived {\r\n  margin-top: 4px;\r\n  padding-top: 4px;\r\n  border-top: 1px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.08));\r\n}\r\n\r\n/* ---------- rows ---------- */\r\n.dts-row {\r\n  --dts-indent: 8px;\r\n  position: relative;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  min-height: 28px;\r\n  padding: 0 8px 0 var(--dts-indent);\r\n  border: 0;\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  background: transparent;\r\n  color: inherit;\r\n  font: inherit;\r\n  font-size: 14px;\r\n  text-align: left;\r\n  cursor: pointer;\r\n  user-select: none;\r\n}\r\n\r\n.dts-row:hover {\r\n  background: var(--dsw-specific-sidebar-nav-item-hover, rgba(38, 49, 72, 0.06));\r\n}\r\n\r\n.dts-row--group {\r\n  min-height: 34px;\r\n  font-weight: 500;\r\n}\r\n\r\n.dts-row--topic {\r\n  min-height: 28px;\r\n}\r\n\r\n.dts-row--topic.is-bucket {\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-row--session {\r\n  min-height: 28px;\r\n}\r\n\r\n.dts-row--session.is-archived {\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-row.is-current {\r\n  background: var(--dsw-specific-sidebar-nav-item-active, rgba(38, 49, 72, 0.08));\r\n}\r\n\r\n.dts-row.is-selected {\r\n  box-shadow: inset 0 0 0 1px var(--dsw-alias-link, #4176e6);\r\n}\r\n\r\n.dts-row__title {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n}\r\n\r\n.dts-row__text {\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n/* The stock workspace row is just its name; the meta appears with the hover strip. */\r\n.dts-row--group .dts-row__count {\r\n  display: none;\r\n}\r\n\r\n.dts-row--group:hover .dts-row__count,\r\n.dts-row--group:focus-within .dts-row__count {\r\n  display: inline;\r\n}\r\n\r\n.dts-row__count {\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.dts-row__aside {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 2px;\r\n  margin-left: auto;\r\n  flex: 0 0 auto;\r\n}\r\n\r\n.dts-row__time {\r\n  font-size: 12px;\r\n  line-height: 18px;\r\n  color: var(--dsw-alias-label-caption, #adb2b8);\r\n  white-space: nowrap;\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.dts-row__actions {\r\n  display: none;\r\n  align-items: center;\r\n  gap: 2px;\r\n}\r\n\r\n/* The stock row swaps its timestamp for the action strip: neither reserves space at rest. */\r\n.dts-row:hover .dts-row__actions,\r\n.dts-row:focus-within .dts-row__actions {\r\n  display: inline-flex;\r\n}\r\n\r\n.dts-row--session:hover .dts-row__time,\r\n.dts-row--session:focus-within .dts-row__time {\r\n  display: none;\r\n}\r\n\r\n/* Like the stock row, the pin marker yields to the hover strip — but only to :hover, so a\r\n   button that keeps focus after the click cannot keep the marker hidden forever. */\r\n.dts-row--session:hover .dts-row__pin {\r\n  display: none;\r\n}\r\n\r\n/* The hover strip buttons are as small as the stock row allows: 24px hit area, 16px glyph. */\r\n.dts-row__act.dts-iconbtn {\r\n  width: 24px;\r\n  height: 24px;\r\n  border-radius: var(--dsw-radius-xs, 4px);\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-row__act.dts-iconbtn:hover:not(:disabled) {\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.08));\r\n}\r\n\r\n.dts-row__chevron {\r\n  flex: 0 0 auto;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-row__folder {\r\n  flex: 0 0 auto;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-row__pin {\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n  flex: 0 0 auto;\r\n  display: inline-flex;\r\n  align-items: center;\r\n}\r\n\r\n.dts-row__check {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  flex: 0 0 auto;\r\n}\r\n\r\n/* During hover the row swaps the folder for a caret, exactly like the stock tree. */\r\n.dts-row__slot {\r\n  flex: 0 0 auto;\r\n  width: 16px;\r\n  height: 20px;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-row--topic .dts-row__slot {\r\n  width: 14px;\r\n}\r\n\r\n.dts-caret {\r\n  display: none;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.dts-caret__icon {\r\n  fill: currentColor;\r\n  stroke: none;\r\n  width: 14px;\r\n  height: 14px;\r\n  transition: transform 0.15s var(--ds-ease-in-out, ease-in-out);\r\n}\r\n\r\n.dts-caret__icon.is-open {\r\n  transform: rotate(90deg);\r\n}\r\n\r\n.dts-folder {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-folder.is-active {\r\n  color: var(--dsw-alias-link, #4176e6);\r\n}\r\n\r\n.dts-row--group:hover .dts-folder,\r\n.dts-row--group:focus-visible .dts-folder {\r\n  display: none;\r\n}\r\n\r\n.dts-row--group:hover .dts-caret,\r\n.dts-row--group:focus-visible .dts-caret,\r\n.dts-row--topic:hover .dts-caret,\r\n.dts-row--topic:focus-visible .dts-caret {\r\n  display: inline-flex;\r\n}\r\n\r\n/* ---------- composer topic chip ---------- */\r\n/* Lives inside the native composer row, right after the workspace picker. */\r\n.dts-composer-slot {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  min-width: 0;\r\n}\r\n\r\n.dts-composer-topic {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  height: 28px;\r\n  max-width: 180px;\r\n  padding: 0 6px;\r\n  margin-left: 2px;\r\n  border: 0;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: transparent;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n  font: inherit;\r\n  font-size: 14px;\r\n  line-height: 20px;\r\n  cursor: pointer;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-composer-topic:hover {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.06));\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n}\r\n\r\n.dts-composer-topic.is-set {\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n}\r\n\r\n.dts-composer-topic__label {\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n}\r\n\r\n.dts-composer-topic__caret {\r\n  color: var(--dsw-alias-label-caption, #adb2b8);\r\n}\r\n\r\n/* ---------- status dot ---------- */\r\n.dts-dot {\r\n  width: 6px;\r\n  height: 6px;\r\n  border-radius: 50%;\r\n  flex: 0 0 auto;\r\n  background: var(--dsw-alias-state-idle-primary, #d4d4d4);\r\n}\r\n\r\n.dts-dot--ongoing {\r\n  background: var(--dsw-alias-state-business-primary, #4176e6);\r\n  animation: dts-pulse 1.4s ease-in-out infinite;\r\n}\r\n\r\n.dts-dot--done {\r\n  background: var(--dsw-alias-state-success-primary, #22c55e);\r\n}\r\n\r\n.dts-dot--warning {\r\n  background: var(--dsw-alias-state-warn-primary, #f59e0b);\r\n}\r\n\r\n.dts-dot--idle {\r\n  background: transparent;\r\n  box-shadow: inset 0 0 0 1px var(--dsw-alias-border-l4, rgba(0, 0, 0, 0.22));\r\n}\r\n\r\n@keyframes dts-pulse {\r\n  0%, 100% { opacity: 1; }\r\n  50% { opacity: 0.35; }\r\n}\r\n\r\n/* ---------- checkbox ---------- */\r\n.dts-check {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  position: relative;\r\n  width: 16px;\r\n  height: 16px;\r\n}\r\n\r\n.dts-check input {\r\n  position: absolute;\r\n  inset: 0;\r\n  margin: 0;\r\n  opacity: 0;\r\n  cursor: pointer;\r\n}\r\n\r\n.dts-check__box {\r\n  width: 14px;\r\n  height: 14px;\r\n  border-radius: var(--dsw-radius-xs, 4px);\r\n  border: 1px solid var(--dsw-alias-border-l4, rgba(0, 0, 0, 0.25));\r\n  background: var(--dsw-alias-bg-base, #fff);\r\n  display: inline-block;\r\n  position: relative;\r\n}\r\n\r\n.dts-check input:checked + .dts-check__box,\r\n.dts-check input:indeterminate + .dts-check__box {\r\n  background: var(--dsw-alias-link, #4176e6);\r\n  border-color: transparent;\r\n}\r\n\r\n.dts-check input:checked + .dts-check__box::after {\r\n  content: '';\r\n  position: absolute;\r\n  left: 4px;\r\n  top: 1px;\r\n  width: 4px;\r\n  height: 8px;\r\n  border: solid #fff;\r\n  border-width: 0 2px 2px 0;\r\n  transform: rotate(45deg);\r\n}\r\n\r\n.dts-check input:indeterminate + .dts-check__box::after {\r\n  content: '';\r\n  position: absolute;\r\n  left: 2px;\r\n  top: 5px;\r\n  width: 8px;\r\n  height: 2px;\r\n  background: #fff;\r\n}\r\n\r\n.dts-check.is-disabled {\r\n  opacity: 0.5;\r\n}\r\n\r\n/* ---------- floating surfaces ---------- */\r\n.dts-pop {\r\n  z-index: 1200;\r\n  display: flex;\r\n  flex-direction: column;\r\n  max-height: 60vh;\r\n  padding: 4px;\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  background: var(--dsw-specific-menu, rgba(248, 249, 250, 0.92));\r\n  -webkit-backdrop-filter: blur(24px) saturate(1.6);\r\n  backdrop-filter: blur(24px) saturate(1.6);\r\n  border: 1px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.08));\r\n  box-shadow: 0 8px 24px rgba(15, 17, 21, 0.14);\r\n  overflow: hidden;\r\n  font-size: 14px;\r\n}\r\n\r\n.dts-pop__head,\r\n.dts-pop__foot {\r\n  padding: 4px 8px;\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-pop__foot {\r\n  border-top: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.05));\r\n  padding-top: 2px;\r\n}\r\n\r\n.dts-pop__list {\r\n  overflow-y: auto;\r\n  min-height: 0;\r\n}\r\n\r\n.dts-pop__empty {\r\n  padding: 8px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-menu__item {\r\n  display: flex;\r\n  align-items: center;\r\n  flex: 0 0 auto;\r\n  gap: 8px;\r\n  width: 100%;\r\n  min-height: 34px;\r\n  padding: 0 8px;\r\n  border: 0;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: transparent;\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  font: inherit;\r\n  font-size: 14px;\r\n  text-align: left;\r\n  cursor: pointer;\r\n}\r\n\r\n.dts-menu__item:hover:not(:disabled) {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.06));\r\n}\r\n\r\n.dts-menu__item.is-danger {\r\n  color: var(--dsw-alias-state-error-primary, #ec1313);\r\n}\r\n\r\n.dts-menu__item:disabled {\r\n  opacity: 0.45;\r\n  cursor: not-allowed;\r\n}\r\n\r\n.dts-menu__label {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  display: flex;\r\n  flex-direction: column;\r\n}\r\n\r\n.dts-menu__hint {\r\n  color: var(--dsw-alias-label-caption, #adb2b8);\r\n  font-size: 12px;\r\n  font-variant-numeric: tabular-nums;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-menu__icon {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 16px;\r\n  height: 16px;\r\n  color: var(--dsw-alias-menu-icon, #353638);\r\n}\r\n\r\n.dts-menu__item.is-danger .dts-menu__icon {\r\n  color: inherit;\r\n}\r\n\r\n.dts-menu__sep {\r\n  flex: 0 0 auto;\r\n  height: 1px;\r\n  margin: 4px 6px;\r\n  background: var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.06));\r\n}\r\n\r\n.dts-menu__item--workspace {\r\n  min-height: 46px;\r\n  padding-top: 5px;\r\n  padding-bottom: 5px;\r\n}\r\n\r\n.dts-menu__item--workspace .dts-menu__label {\r\n  gap: 1px;\r\n}\r\n\r\n.dts-workspace__name {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-workspace__path {\r\n  font-size: 11px;\r\n  line-height: 14px;\r\n  color: var(--dsw-alias-label-caption, #adb2b8);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n/* ---------- dialogs ---------- */\r\n.dts-scrim {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 1300;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  background: var(--dsw-alias-bg-mask-2, rgba(0, 0, 0, 0.12));\r\n  padding: 16px;\r\n}\r\n\r\n.dts-dialog {\r\n  display: flex;\r\n  flex-direction: column;\r\n  max-height: 86vh;\r\n  width: min(100%, 440px);\r\n  border-radius: var(--dsw-radius-lg, 16px);\r\n  background: var(--dsw-alias-bg-layer-1, #fff);\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  box-shadow: 0 24px 60px rgba(15, 17, 21, 0.24);\r\n  font-size: 14px;\r\n  overflow: hidden;\r\n}\r\n\r\n.dts-dialog__head {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 12px 14px;\r\n  border-bottom: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.05));\r\n}\r\n\r\n.dts-dialog__title {\r\n  flex: 1 1 auto;\r\n  margin: 0;\r\n  font-size: 15px;\r\n  font-weight: 600;\r\n}\r\n\r\n.dts-dialog__body {\r\n  padding: 14px;\r\n  overflow-y: auto;\r\n  min-height: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n}\r\n\r\n.dts-dialog__foot {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 12px 14px;\r\n  border-top: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.05));\r\n}\r\n\r\n.dts-dialog__hint {\r\n  margin: 0;\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-dialog__text {\r\n  margin: 0;\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-field {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6px;\r\n}\r\n\r\n.dts-field__label {\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-field__hint {\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-error {\r\n  margin: 0;\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-state-error-primary, #ec1313);\r\n}\r\n\r\n/* ---------- settings-style dialog (create topic) ----------\r\n   Mirrors the host Modal + SettingsForm metrics: 16/24 medium title, 24px side padding,\r\n   13/500 field labels, 34px hairline inputs, fields separated by a .5px rule, and the\r\n   compact inverted save button the settings pages use. */\r\n.dts-dialog--settings {\r\n  gap: 0;\r\n  width: min(560px, 100%);\r\n  max-height: min(86vh, 720px);\r\n  padding: 0 0 24px;\r\n  border-radius: var(--dsw-radius-panel, 24px);\r\n  background: var(--dsw-alias-bg-layer-2, #fff);\r\n  box-shadow: var(--dsw-elevation-prominent, 0 24px 60px rgba(15, 17, 21, 0.24));\r\n  font-size: 14px;\r\n  animation: dts-dialog-in 0.16s var(--ds-ease-in-out, ease-out);\r\n}\r\n\r\n.dts-scrim:has(.dts-dialog--settings) {\r\n  background: var(--dsw-alias-bg-mask-1, rgba(0, 0, 0, 0.24));\r\n}\r\n\r\n@keyframes dts-dialog-in {\r\n  from { opacity: 0; }\r\n  to { opacity: 1; }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n  .dts-dialog--settings { animation: none; }\r\n}\r\n\r\n.dts-dialog--settings .dts-dialog__head {\r\n  padding: 22px 14px 12px 24px;\r\n  border-bottom: 0;\r\n}\r\n\r\n.dts-dialog--settings .dts-dialog__title {\r\n  font-size: 16px;\r\n  line-height: 24px;\r\n  font-weight: 500;\r\n}\r\n\r\n.dts-dialog__description {\r\n  margin: 0;\r\n  padding: 0 24px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n  font-size: 13px;\r\n  line-height: 20px;\r\n}\r\n\r\n.dts-dialog--settings .dts-dialog__body {\r\n  margin-top: 20px;\r\n  padding: 0 24px;\r\n  gap: 0;\r\n}\r\n\r\n.dts-dialog--settings .dts-dialog__foot {\r\n  justify-content: flex-end;\r\n  padding: 20px 24px 0;\r\n  border-top: 0;\r\n}\r\n\r\n.dts-dialog--settings .dts-dialog__hint {\r\n  padding-top: 12px;\r\n  font-size: 12px;\r\n  line-height: 1.5;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-dialog--settings .dts-field {\r\n  gap: 6px;\r\n  padding: 12px 0;\r\n}\r\n\r\n.dts-dialog--settings .dts-field + .dts-field {\r\n  border-top: .5px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.08));\r\n}\r\n\r\n.dts-dialog--settings .dts-field__label {\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  font-size: 13px;\r\n  font-weight: 500;\r\n  line-height: 1.5;\r\n}\r\n\r\n.dts-dialog--settings .dts-field__hint {\r\n  font-size: 12px;\r\n  line-height: 1.5;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-dialog--settings .dts-input {\r\n  height: 34px;\r\n  padding: 0 12px;\r\n  border: .5px solid var(--dsw-alias-border-l4, rgba(0, 0, 0, 0.14));\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  background: var(--dsw-alias-bg-layer-3, #fff);\r\n  font-size: 13px;\r\n  line-height: 1.5;\r\n}\r\n\r\n.dts-dialog--settings .dts-input:focus-visible {\r\n  outline: none;\r\n  border-color: var(--dsw-alias-state-business-primary, #4176e6);\r\n}\r\n\r\n.dts-settings-value {\r\n  display: flex;\r\n  align-items: center;\r\n  min-height: 34px;\r\n  padding: 0 12px;\r\n  border: .5px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.08));\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  background: var(--dsw-alias-bg-layer-3, #fff);\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n  font-size: 13px;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-dialog--settings .dts-select {\r\n  position: relative;\r\n  display: flex;\r\n}\r\n\r\n.dts-dialog--settings .dts-select select {\r\n  appearance: none;\r\n  width: 100%;\r\n  height: 34px;\r\n  padding: 0 32px 0 12px;\r\n  border: .5px solid var(--dsw-alias-border-l4, rgba(0, 0, 0, 0.14));\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  background: var(--dsw-alias-bg-layer-3, #fff);\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  font: inherit;\r\n  font-size: 13px;\r\n  line-height: 1.5;\r\n  cursor: pointer;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-dialog--settings .dts-select select:focus-visible {\r\n  outline: none;\r\n  border-color: var(--dsw-alias-state-business-primary, #4176e6);\r\n}\r\n\r\n.dts-dialog--settings .dts-select select:disabled {\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n  cursor: default;\r\n}\r\n\r\n.dts-dialog--settings .dts-select__caret {\r\n  position: absolute;\r\n  top: 50%;\r\n  right: 10px;\r\n  transform: translateY(-50%);\r\n  pointer-events: none;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-dialog--settings .dts-emojis {\r\n  max-width: none;\r\n  gap: 6px;\r\n}\r\n\r\n.dts-dialog--settings .dts-emojis__item {\r\n  width: 34px;\r\n  height: 34px;\r\n  border: .5px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.08));\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  background: var(--dsw-alias-bg-layer-3, #fff);\r\n  font-size: 17px;\r\n}\r\n\r\n.dts-dialog--settings .dts-emojis__item:hover {\r\n  background: var(--dsw-alias-bg-layer-4, rgba(38, 49, 72, 0.06));\r\n}\r\n\r\n.dts-dialog--settings .dts-emojis__item.is-active {\r\n  border-color: var(--dsw-alias-state-business-primary, #4176e6);\r\n  background: var(--dsw-alias-bg-layer-1, #fff);\r\n}\r\n\r\n.dts-dialog--settings .dts-picker {\r\n  gap: 8px;\r\n}\r\n\r\n.dts-dialog--settings .dts-picker__bar {\r\n  margin-top: 2px;\r\n}\r\n\r\n.dts-dialog--settings .dts-picker__list {\r\n  max-height: 208px;\r\n  padding: 4px;\r\n  border: .5px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.08));\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  background: var(--dsw-alias-bg-layer-1, #fff);\r\n}\r\n\r\n.dts-dialog--settings .dts-picker__row {\r\n  min-height: 32px;\r\n  padding: 0 8px;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n}\r\n\r\n.dts-dialog--settings .dts-picker__row:hover {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.05));\r\n}\r\n\r\n.dts-dialog--settings .dts-picker__title {\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-dialog--settings .dts-btn {\r\n  height: 30px;\r\n  padding: 0 14px;\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-dialog--settings .dts-btn--primary {\r\n  background: var(--dsw-alias-label-primary, #0f1115);\r\n  border-color: transparent;\r\n  color: var(--dsw-alias-bg-layer-3, #fff);\r\n}\r\n\r\n.dts-dialog--settings .dts-btn--primary:hover:not(:disabled) {\r\n  background: var(--dsw-alias-label-primary, #0f1115);\r\n  opacity: 0.88;\r\n}\r\n\r\n.dts-dialog--settings .dts-btn--ghost {\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-warning {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 6px;\r\n  padding: 8px;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: var(--dsw-alias-state-warn-tertiary, rgba(245, 158, 11, 0.1));\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  max-height: 44vh;\r\n  overflow-y: auto;\r\n}\r\n\r\n.dts-list__item {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  min-height: 32px;\r\n  padding: 0 8px;\r\n  border: 0;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: transparent;\r\n  color: inherit;\r\n  font: inherit;\r\n  cursor: pointer;\r\n  text-align: left;\r\n}\r\n\r\n.dts-list__item:hover:not(:disabled) {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.06));\r\n}\r\n\r\n.dts-list__label {\r\n  flex: 1 1 auto;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-list__count,\r\n.dts-picker__count {\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-list__empty,\r\n.dts-picker__empty {\r\n  padding: 8px;\r\n  font-size: 13px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n.dts-picker {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6px;\r\n}\r\n\r\n.dts-picker__bar {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n}\r\n\r\n.dts-picker__list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 1px;\r\n  max-height: 180px;\r\n  overflow-y: auto;\r\n  border: 1px solid var(--dsw-alias-border-l2, rgba(0, 0, 0, 0.08));\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  padding: 2px;\r\n}\r\n\r\n.dts-picker__row {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  min-height: 28px;\r\n  padding: 0 6px;\r\n  border-radius: var(--dsw-radius-xs, 4px);\r\n  cursor: pointer;\r\n}\r\n\r\n.dts-picker__row.is-on {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.05));\r\n}\r\n\r\n.dts-picker__title {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-picker__ws {\r\n  font-size: 11px;\r\n  color: var(--dsw-alias-label-caption, #adb2b8);\r\n}\r\n\r\n.dts-ack {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  font-size: 13px;\r\n  cursor: pointer;\r\n}\r\n\r\n.dts-result__summary {\r\n  margin: 0;\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-result__progress {\r\n  margin: 0;\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-result__list {\r\n  list-style: none;\r\n  margin: 0;\r\n  padding: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  max-height: 32vh;\r\n  overflow-y: auto;\r\n}\r\n\r\n.dts-result__item {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: 8px;\r\n  padding: 4px 6px;\r\n  border-radius: var(--dsw-radius-xs, 4px);\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.04));\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-result__item.is-bad {\r\n  box-shadow: inset 0 0 0 1px var(--dsw-alias-state-error-primary, rgba(236, 19, 19, 0.4));\r\n}\r\n\r\n.dts-result__item.is-warn {\r\n  box-shadow: inset 0 0 0 1px var(--dsw-alias-state-warn-primary, rgba(245, 158, 11, 0.45));\r\n}\r\n\r\n.dts-result__label {\r\n  flex: 0 1 auto;\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dts-result__detail {\r\n  flex: 1 1 auto;\r\n  text-align: right;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n  font-size: 12px;\r\n}\r\n\r\n.dts-result__empty {\r\n  padding: 8px;\r\n  font-size: 13px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n}\r\n\r\n/* ---------- batch bar, banners, misc ---------- */\r\n.dts-batchbar {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  flex-wrap: wrap;\r\n  padding: 6px 8px;\r\n  border-top: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.05));\r\n  background: var(--dsw-specific-sidebar-fill, #f9fafb);\r\n}\r\n\r\n.dts-batchbar__count {\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-batchbar__progress {\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-link, #4176e6);\r\n}\r\n\r\n.dts-batchbar__warn {\r\n  flex-basis: 100%;\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-state-error-primary, #ec1313);\r\n}\r\n\r\n.dts-banner {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  margin: 0 8px 6px;\r\n  padding: 6px 8px;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  font-size: 12px;\r\n  background: var(--dsw-alias-state-warn-tertiary, rgba(245, 158, 11, 0.12));\r\n  color: var(--dsw-alias-label-primary, #0f1115);\r\n}\r\n\r\n.dts-banner__close {\r\n  margin-left: auto;\r\n  border: 0;\r\n  background: transparent;\r\n  color: inherit;\r\n  cursor: pointer;\r\n  display: inline-flex;\r\n}\r\n\r\n.dts-empty,\r\n.dts-placeholder,\r\n.dts-note {\r\n  padding: 12px 8px;\r\n  font-size: 13px;\r\n  color: var(--dsw-alias-label-tertiary, #81858c);\r\n  text-align: center;\r\n}\r\n\r\n.dts-note {\r\n  padding: 4px;\r\n  font-size: 12px;\r\n}\r\n\r\n.dts-mark {\r\n  background: var(--dsw-alias-state-warn-tertiary, rgba(245, 158, 11, 0.28));\r\n  color: inherit;\r\n  border-radius: 2px;\r\n}\r\n\r\n/* ---------- session hover card ---------- */\r\n/* Mirrors the stock tooltip: dark surface, title, relative time, and state or archive badge. */\r\n.dts-tip {\r\n  position: fixed;\r\n  z-index: 1500;\r\n  width: max-content;\r\n  max-width: 244px;\r\n  padding: 12px 16px;\r\n  border-radius: var(--dsw-radius-lg, 16px);\r\n  background: var(--dsw-alias-tooltip-bg, #2c2c2e);\r\n  color: #fff;\r\n  font-size: 14px;\r\n  line-height: 1.55;\r\n  box-shadow: 0 10px 28px rgba(15, 17, 21, 0.24);\r\n  pointer-events: none;\r\n}\r\n\r\n.dts-tip__title {\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.dts-tip__meta {\r\n  margin-top: 6px;\r\n  color: rgba(255, 255, 255, 0.55);\r\n  font-size: 13px;\r\n}\r\n\r\n.dts-tip__badge {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n}\r\n\r\n.dts-tip__dot {\r\n  width: 6px;\r\n  height: 6px;\r\n  border-radius: 50%;\r\n  background: currentColor;\r\n  opacity: 0.75;\r\n  flex: 0 0 auto;\r\n}\r\n\r\n.dts-toast {\r\n  position: fixed;\r\n  left: 50%;\r\n  bottom: 24px;\r\n  transform: translateX(-50%);\r\n  z-index: 1400;\r\n  max-width: min(90vw, 520px);\r\n  padding: 8px 14px;\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  background: var(--dsw-alias-toast-bg, #353638);\r\n  color: var(--dsw-alias-toast-label, #fff);\r\n  font-size: 13px;\r\n  box-shadow: 0 10px 24px rgba(15, 17, 21, 0.24);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.dts-toast.is-bad {\r\n  background: var(--dsw-alias-state-error-primary, #ec1313);\r\n  color: #fff;\r\n}\r\n\r\n.dts-busy {\r\n  position: absolute;\r\n  right: 10px;\r\n  bottom: 10px;\r\n  padding: 3px 8px;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: var(--dsw-alias-bg-layer-1, rgba(38, 49, 72, 0.05));\r\n  font-size: 12px;\r\n  color: var(--dsw-alias-label-secondary, #61666b);\r\n}\r\n\r\n.dts-icon {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  flex: 0 0 auto;\r\n  width: 16px;\r\n  height: 16px;\r\n  line-height: 0;\r\n}\r\n\r\n.dts-icon > svg {\r\n  width: 100%;\r\n  height: 100%;\r\n  display: block;\r\n}\r\n\r\n/* ---------- drag & drop, inline rename, progressive reveal ---------- */\r\n.dts-row[data-dragging='true'] {\r\n  opacity: 0.45;\r\n}\r\n\r\n.dts-row--topic.is-drop-ok {\r\n  box-shadow: inset 0 0 0 1px var(--dsw-alias-link, #4176e6);\r\n  background: var(--dsw-alias-interactive-bg-hover-accent, rgba(65, 118, 230, 0.1));\r\n}\r\n\r\n.dts-row--topic.is-drop-no {\r\n  box-shadow: inset 0 0 0 1px var(--dsw-alias-state-error-primary, rgba(236, 19, 19, 0.5));\r\n  opacity: 0.7;\r\n}\r\n\r\n.dts-input--inline {\r\n  height: 22px;\r\n  font-size: 13px;\r\n  padding: 0 6px;\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n}\r\n\r\n.dts-reveal {\r\n  align-self: flex-start;\r\n  margin: 2px 0 2px var(--dts-indent, 12px);\r\n  padding: 2px 6px;\r\n  border: 0;\r\n  border-radius: var(--dsw-radius-xs, 4px);\r\n  background: transparent;\r\n  color: var(--dsw-alias-link, #4176e6);\r\n  font: inherit;\r\n  font-size: 12px;\r\n  cursor: pointer;\r\n}\r\n\r\n.dts-reveal:hover {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.05));\r\n}\r\n\r\n.dts-row--topic.is-pending::after {\r\n  content: '';\r\n  position: absolute;\r\n  inset: 0;\r\n  border-radius: var(--dsw-radius-md, 12px);\r\n  box-shadow: inset 0 0 0 1px var(--dsw-alias-link, rgba(65, 118, 230, 0.45));\r\n  animation: dts-pulse 1.4s ease-in-out infinite;\r\n  pointer-events: none;\r\n}\r\n\r\n/* ---------- topic markers: emoji, or a plain dash when there is none ---------- */\r\n.dts-emoji {\r\n  font-size: 14px;\r\n  line-height: 1;\r\n  flex: 0 0 auto;\r\n  width: 16px;\r\n  text-align: center;\r\n}\r\n\r\n.dts-dash {\r\n  width: 8px;\r\n  height: 2px;\r\n  border-radius: 1px;\r\n  flex: 0 0 auto;\r\n  background: var(--dsw-alias-label-caption, #adb2b8);\r\n  transform: translateY(1px);\r\n}\r\n\r\n.dts-menu__icon .dts-emoji,\r\n.dts-menu__icon .dts-dash,\r\n.dts-list__item .dts-emoji,\r\n.dts-list__item .dts-dash {\r\n  display: inline-block;\r\n}\r\n\r\n.dts-emojis {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 2px;\r\n  max-width: 320px;\r\n}\r\n\r\n.dts-emojis__item {\r\n  width: 30px;\r\n  height: 30px;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  border: 1px solid transparent;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: transparent;\r\n  font-size: 16px;\r\n  line-height: 1;\r\n  cursor: pointer;\r\n}\r\n\r\n.dts-emojis__item:hover {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(38, 49, 72, 0.06));\r\n}\r\n\r\n.dts-emojis__item.is-active {\r\n  border-color: var(--dsw-alias-link, #4176e6);\r\n  background: var(--dsw-alias-interactive-bg-hover-accent, rgba(65, 118, 230, 0.1));\r\n}\r\n\r\n.dts-chip .dts-emoji {\r\n  width: auto;\r\n}\r\n";

